// This script is generated by Gemini
using UnityEngine;

public class Dumpster : MonoBehaviour
{
    [Header("Dumpster Settings")]
    public Transform player;
    public float interactionRadius = 2.5f;
    
    [Header("Audio")]
    public AudioSource dumpAudio;

    void Start()
    {
        if (player == null)
        {
            GameObject playerObj = GameObject.FindGameObjectWithTag("Player");
            if (playerObj != null) player = playerObj.transform;
        }
    }

    void Update()
    {
        if (player == null || ScoreManager.Instance == null) return;

        // Flatten the Y axis so the distance check is a perfect cylinder
        Vector3 flatPlayerPosition = new Vector3(player.position.x, transform.position.y, player.position.z);
        float distance = Vector3.Distance(transform.position, flatPlayerPosition);

        // If the player walks close enough to the dumpster AND has trash in their bag
        if (distance <= interactionRadius && ScoreManager.Instance.currentBagLoad > 0)
        {
            EmptyTrashBag();
        }
    }

    private void EmptyTrashBag()
    {
        ScoreManager.Instance.EmptyBag();
        
        if (dumpAudio != null) 
        {
            dumpAudio.Play();
        }
        
        Debug.Log("Dumpster Emptied!");
    }

    void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.blue;
        Gizmos.DrawWireSphere(transform.position, interactionRadius);
    }
}